-- ============================================================
-- BASE DE DATOS COMPLETA: colegiocristomorado
-- Sistema Web de Gestión Académica — I.E. N.º 2092 Cristo Morado
-- Incluye los Sprints 1 a 6 + vista del docente + historial de entregas.
-- Datos de prueba al 14/10/2026 (III Bimestre activo).
-- ============================================================
--
-- IMPORTANTE:
--   * Este script BORRA las tablas del proyecto y las crea de nuevo
--     con datos de prueba.
--   * Ejecútalo conectado a la base "colegiocristomorado".
--     Si no existe, créala antes (en otra conexión):
--         CREATE DATABASE colegiocristomorado;
--   * Las tablas coinciden con las entidades del backend
--     (spring.jpa.hibernate.ddl-auto=update no tendrá nada que agregar).
--
-- USUARIOS DE PRUEBA (usuario / contraseña). Todos los demás usan la contraseña 1234:
--   admin123      / admin   -> Administrador
--   DIR20262926   / 1234    -> Director(a), todos los permisos
--   DIR42444633   / 1234    -> Secretaria, permiso Comunicados
--   DIR99557828   / 1234    -> Personal sin permisos
--   DOC45678912   / 1234    -> Carlos Mendoza: tutor de 5° Primaria A (Matemática, Ciencia, Personal Social, Arte)
--                              y Matemática de 4° Primaria B
--   DOC40123456   / 1234    -> Rosa Quispe: Comunicación e Inglés de 5° A, Comunicación de 4° B y 5° B
--   ALU87654321   / 1234    -> Juan Pérez García (5° Primaria A): tiene "Entrega 1" y "Entrega 2"
--   ALU71234560   / 1234    -> Lucía Pérez García (5° Primaria A): envió tarde un trabajo
--   ALU91234567   / 1234    -> María López Torres (4° Primaria B)
--   APO76543210   / 1234    -> Juan Pérez Rojas, padre de Juan y Lucía
--   APO65432109   / 1234    -> Ana García López, madre de Juan y Lucía
-- La lista completa de usuarios sale al final del script (consulta de verificación).
-- ============================================================


-- ============================================================
-- 1. ELIMINAR TABLAS EXISTENTES
-- ============================================================

DROP TABLE IF EXISTS
    mensaje_borradores,
    citas,
    entrega_envios,
    sesiones_asistencia,
    carpetas,
    disponibilidades,
    notas_historial,
    notas,
    evaluaciones,
    asistencias,
    entrega_respuestas,
    entregas,
    pregunta_opciones,
    preguntas_cuestionario,
    actividades,
    materiales,
    archivos,
    horario_bloques,
    seccion_cursos,
    secciones,
    cursos,
    periodos,
    personal_permisos,
    personal,
    codigos_verificacion,
    mensaje_destinatarios,
    mensajes,
    comunicado_lecturas,
    comunicado_secciones,
    comunicado_destinatarios,
    comunicados,
    estudiante_familiar,
    docentes,
    estudiantes,
    padres_familia,
    usuarios
CASCADE;


-- ============================================================
-- 2. USUARIOS (cuentas de acceso)
-- Usuario = PREFIJO + N.º de documento:
--   ALU (alumno), DOC (docente), APO (apoderado), DIR (directiva).
--   El administrador tiene usuario libre.
-- ============================================================

CREATE TABLE usuarios (
    id                BIGSERIAL PRIMARY KEY,
    nombre            VARCHAR(100) NOT NULL,
    usuario           VARCHAR(100) NOT NULL UNIQUE,
    correo            VARCHAR(150) UNIQUE,          -- Gmail vinculado y verificado por el propio usuario
    correo_verificado BOOLEAN      NOT NULL DEFAULT FALSE,
    password          VARCHAR(255) NOT NULL,
    rol               VARCHAR(50)  NOT NULL,        -- ADMIN | DIRECTIVO | DOCENTE | ALUMNO | PADRE
    estado            BOOLEAN      NOT NULL DEFAULT TRUE,
    fecha_registro    TIMESTAMP    NOT NULL DEFAULT NOW(),
    foto              TEXT,                         -- foto de perfil (data URL)
    telefono          VARCHAR(20),                  -- cuentas sin registro de persona (administrador)
    direccion         VARCHAR(200)
);


-- ============================================================
-- 3. PERSONAS: estudiantes, padres, docentes y directiva
-- ============================================================

CREATE TABLE estudiantes (
    id               BIGSERIAL PRIMARY KEY,
    nombre_completo  VARCHAR(150) NOT NULL,
    tipo_documento   VARCHAR(10)  NOT NULL DEFAULT 'DNI'
                     CHECK (tipo_documento IN ('DNI', 'CE', 'PASAPORTE', 'OTRO')),
    dni              VARCHAR(15)  NOT NULL UNIQUE,
    foto_url         VARCHAR(500),
    fecha_nacimiento DATE,
    genero           VARCHAR(20),
    nacionalidad     VARCHAR(60),
    direccion        VARCHAR(200),
    telefono         VARCHAR(20),
    grado            VARCHAR(20),                   -- "1° Primaria" ... "5° Secundaria"; NULL = sin matrícula
    seccion          VARCHAR(5),                    -- letra de la sección
    anio_ingreso     INTEGER,
    estado           VARCHAR(20)  NOT NULL DEFAULT 'Activo',
    fecha_registro   TIMESTAMP    NOT NULL DEFAULT NOW(),
    usuario_id       BIGINT UNIQUE REFERENCES usuarios(id) ON DELETE SET NULL
);

CREATE TABLE padres_familia (
    id               BIGSERIAL PRIMARY KEY,
    nombre_completo  VARCHAR(150) NOT NULL,
    tipo_documento   VARCHAR(10)  NOT NULL DEFAULT 'DNI'
                     CHECK (tipo_documento IN ('DNI', 'CE', 'PASAPORTE', 'OTRO')),
    dni              VARCHAR(15)  NOT NULL UNIQUE,
    fecha_nacimiento DATE,
    telefono         VARCHAR(20)  NOT NULL,
    correo           VARCHAR(150),                  -- correo de contacto
    direccion        VARCHAR(200),
    estado           VARCHAR(20)  NOT NULL DEFAULT 'Activo',
    fecha_registro   TIMESTAMP    NOT NULL DEFAULT NOW(),
    usuario_id       BIGINT UNIQUE REFERENCES usuarios(id) ON DELETE SET NULL
);

-- Vínculo padre-hijo (N a N) con el parentesco
CREATE TABLE estudiante_familiar (
    id               BIGSERIAL PRIMARY KEY,
    estudiante_id    BIGINT      NOT NULL REFERENCES estudiantes(id) ON DELETE CASCADE,
    padre_familia_id BIGINT      NOT NULL REFERENCES padres_familia(id) ON DELETE CASCADE,
    parentesco       VARCHAR(20) NOT NULL,          -- Padre, Madre, Apoderado, Tutor, Otro familiar
    CONSTRAINT estudiante_familiar_unique UNIQUE (estudiante_id, padre_familia_id)
);

CREATE TABLE docentes (
    id                 BIGSERIAL PRIMARY KEY,
    nombre_completo    VARCHAR(150) NOT NULL,
    tipo_documento     VARCHAR(10)  NOT NULL DEFAULT 'DNI'
                       CHECK (tipo_documento IN ('DNI', 'CE', 'PASAPORTE', 'OTRO')),
    dni                VARCHAR(15)  NOT NULL UNIQUE,
    foto_url           VARCHAR(500),
    fecha_nacimiento   DATE,
    genero             VARCHAR(20),
    telefono           VARCHAR(20),
    correo             VARCHAR(150),
    direccion          VARCHAR(200),
    especialidad       VARCHAR(100),
    titulo_profesional VARCHAR(150),
    fecha_ingreso      DATE,
    estado             VARCHAR(20)  NOT NULL DEFAULT 'Activo',
    usuario_id         BIGINT UNIQUE REFERENCES usuarios(id) ON DELETE SET NULL,
    fecha_registro     TIMESTAMP    NOT NULL DEFAULT NOW()
);

-- Personal Staff / Directiva (usuario DIR + documento, rol DIRECTIVO)
CREATE TABLE personal (
    id               BIGSERIAL PRIMARY KEY,
    tipo_documento   VARCHAR(10)  NOT NULL DEFAULT 'DNI'
                     CHECK (tipo_documento IN ('DNI', 'CE', 'PASAPORTE', 'OTRO')),
    numero_documento VARCHAR(15)  NOT NULL UNIQUE,
    nombres          VARCHAR(100) NOT NULL,
    apellido_paterno VARCHAR(60)  NOT NULL,
    apellido_materno VARCHAR(60),
    correo           VARCHAR(150),
    telefono         VARCHAR(20),
    fecha_nacimiento DATE,
    direccion        VARCHAR(200),
    cargo            VARCHAR(100),
    estado           VARCHAR(20)  NOT NULL DEFAULT 'Activo',
    usuario_id       BIGINT UNIQUE REFERENCES usuarios(id) ON DELETE SET NULL,
    fecha_registro   TIMESTAMP    NOT NULL DEFAULT NOW()
);

-- Permisos que el administrador da a cada miembro de la Directiva
CREATE TABLE personal_permisos (
    personal_id BIGINT      NOT NULL REFERENCES personal(id) ON DELETE CASCADE,
    permiso     VARCHAR(30) NOT NULL
                CHECK (permiso IN ('COMUNICADOS', 'REPORTES', 'ACADEMICO', 'USUARIOS', 'PERMISOS')),
    PRIMARY KEY (personal_id, permiso)
);

-- Códigos enviados al Gmail (solo se guarda el hash)
CREATE TABLE codigos_verificacion (
    id             BIGSERIAL PRIMARY KEY,
    usuario_id     BIGINT       NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    tipo           VARCHAR(30)  NOT NULL
                   CHECK (tipo IN ('VINCULAR_CORREO', 'CAMBIO_PASSWORD', 'RECUPERAR_PASSWORD')),
    correo         VARCHAR(150) NOT NULL,
    codigo_hash    VARCHAR(64)  NOT NULL,
    expira_en      TIMESTAMP    NOT NULL,
    intentos       INTEGER      NOT NULL DEFAULT 0,
    usado          BOOLEAN      NOT NULL DEFAULT FALSE,
    fecha_creacion TIMESTAMP    NOT NULL DEFAULT NOW()
);


-- ============================================================
-- 4. COMUNICADOS Y MENSAJERÍA
-- ============================================================

CREATE TABLE comunicados (
    id                  BIGSERIAL PRIMARY KEY,
    titulo              VARCHAR(200) NOT NULL,
    contenido           TEXT         NOT NULL,      -- HTML simple del editor
    imagen              TEXT,                       -- data URL o enlace (opcional)
    anuncio             BOOLEAN      NOT NULL DEFAULT FALSE,
    autor_id            BIGINT REFERENCES usuarios(id) ON DELETE SET NULL,
    fecha_creacion      TIMESTAMP    NOT NULL DEFAULT NOW(),
    fecha_actualizacion TIMESTAMP
);

-- Grupos a los que va dirigido
CREATE TABLE comunicado_destinatarios (
    comunicado_id BIGINT      NOT NULL REFERENCES comunicados(id) ON DELETE CASCADE,
    grupo         VARCHAR(30) NOT NULL
                  CHECK (grupo IN ('TODOS', 'ADMINISTRATIVO', 'DOCENTES', 'ALUMNOS', 'PADRES')),
    PRIMARY KEY (comunicado_id, grupo)
);

-- Secciones a las que se limita (vacío = todo el colegio). Los docentes siempre eligen sus secciones.
CREATE TABLE comunicado_secciones (
    comunicado_id BIGINT NOT NULL REFERENCES comunicados(id) ON DELETE CASCADE,
    seccion_id    BIGINT NOT NULL,
    PRIMARY KEY (comunicado_id, seccion_id)
);

CREATE TABLE comunicado_lecturas (
    id            BIGSERIAL PRIMARY KEY,
    comunicado_id BIGINT    NOT NULL,
    usuario_id    BIGINT    NOT NULL,
    fecha_lectura TIMESTAMP NOT NULL DEFAULT NOW(),
    CONSTRAINT comunicado_lecturas_unique UNIQUE (comunicado_id, usuario_id)
);

CREATE TABLE mensajes (
    id                  BIGSERIAL PRIMARY KEY,
    remitente_id        BIGINT REFERENCES usuarios(id) ON DELETE SET NULL,  -- NULL en avisos automáticos
    asunto              VARCHAR(200) NOT NULL,
    contenido           TEXT         NOT NULL,
    fecha_envio         TIMESTAMP    NOT NULL DEFAULT NOW(),
    respuesta_a_id      BIGINT,
    eliminado_remitente BOOLEAN      NOT NULL DEFAULT FALSE,
    aviso_sistema       BOOLEAN      NOT NULL DEFAULT FALSE  -- "Avisos del colegio"
);

CREATE TABLE mensaje_destinatarios (
    id              BIGSERIAL PRIMARY KEY,
    mensaje_id      BIGINT  NOT NULL REFERENCES mensajes(id) ON DELETE CASCADE,
    destinatario_id BIGINT  NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    leido           BOOLEAN NOT NULL DEFAULT FALSE,
    fecha_lectura   TIMESTAMP,
    eliminado       BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT mensaje_destinatarios_unique UNIQUE (mensaje_id, destinatario_id)
);

-- Borradores de la mensajería: solo los ve su autor, no llegan a nadie hasta enviarlos.
CREATE TABLE mensaje_borradores (
    id                  BIGSERIAL PRIMARY KEY,
    usuario_id          BIGINT       NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    destinatario_id     BIGINT       REFERENCES usuarios(id) ON DELETE SET NULL,
    asunto              VARCHAR(200) NOT NULL DEFAULT '',
    contenido           TEXT         NOT NULL DEFAULT '',
    respuesta_a_id      BIGINT,
    fecha_actualizacion TIMESTAMP    NOT NULL DEFAULT NOW()
);
CREATE INDEX mensaje_borradores_usuario_idx ON mensaje_borradores (usuario_id);


-- ============================================================
-- 5. ACADÉMICO: periodos, cursos, secciones y horarios
-- ============================================================

-- Bimestres del año (solo uno activo)
CREATE TABLE periodos (
    id             BIGSERIAL PRIMARY KEY,
    nombre         VARCHAR(80) NOT NULL,
    anio           INTEGER     NOT NULL,
    bimestre       INTEGER     NOT NULL CHECK (bimestre BETWEEN 1 AND 4),
    fecha_inicio   DATE        NOT NULL,
    fecha_fin      DATE        NOT NULL,
    activo         BOOLEAN     NOT NULL DEFAULT FALSE,
    fecha_registro TIMESTAMP   NOT NULL DEFAULT NOW(),
    CONSTRAINT periodos_anio_bimestre_unique UNIQUE (anio, bimestre)
);

-- Catálogo de cursos
CREATE TABLE cursos (
    id        BIGSERIAL PRIMARY KEY,
    nombre    VARCHAR(80) NOT NULL UNIQUE,
    categoria VARCHAR(20) NOT NULL DEFAULT 'OTROS',
    color     VARCHAR(9)  NOT NULL DEFAULT '#4A1F52',
    estado    VARCHAR(10) NOT NULL DEFAULT 'Activo'
);

-- Secciones (Primaria A = mañana, B = tarde; Secundaria solo A)
CREATE TABLE secciones (
    id             BIGSERIAL PRIMARY KEY,
    grado          VARCHAR(20) NOT NULL,
    letra          VARCHAR(5)  NOT NULL,
    turno          VARCHAR(10) NOT NULL DEFAULT 'Mañana',
    capacidad      INTEGER     NOT NULL DEFAULT 35,
    estado         VARCHAR(10) NOT NULL DEFAULT 'Activa',
    tutor_id       BIGINT REFERENCES docentes(id) ON DELETE SET NULL,
    fecha_registro TIMESTAMP   NOT NULL DEFAULT NOW(),
    CONSTRAINT secciones_grado_letra_unique UNIQUE (grado, letra)
);

-- Cursos de cada sección con su docente
CREATE TABLE seccion_cursos (
    id          BIGSERIAL PRIMARY KEY,
    seccion_id  BIGINT      NOT NULL REFERENCES secciones(id) ON DELETE CASCADE,
    curso_id    BIGINT      NOT NULL REFERENCES cursos(id),
    docente_id  BIGINT REFERENCES docentes(id) ON DELETE SET NULL,
    descripcion VARCHAR(300),
    estado      VARCHAR(10) NOT NULL DEFAULT 'Activo',
    CONSTRAINT seccion_cursos_unique UNIQUE (seccion_id, curso_id)
);

-- Horario semanal (1 = lunes ... 5 = viernes)
CREATE TABLE horario_bloques (
    id               BIGSERIAL PRIMARY KEY,
    seccion_id       BIGINT  NOT NULL REFERENCES secciones(id) ON DELETE CASCADE,
    seccion_curso_id BIGINT  NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    dia              INTEGER NOT NULL CHECK (dia BETWEEN 1 AND 5),
    hora_inicio      TIME    NOT NULL,
    hora_fin         TIME    NOT NULL
);


-- ============================================================
-- 6. AULA VIRTUAL (Sprint 4): archivos, materiales, actividades, entregas, asistencia
-- ============================================================

CREATE TABLE archivos (
    id           BIGSERIAL PRIMARY KEY,
    nombre       VARCHAR(255) NOT NULL,
    tipo_mime    VARCHAR(150) NOT NULL,
    tamanio      BIGINT       NOT NULL,
    datos        BYTEA        NOT NULL,             -- máx. 10 MB
    subido_por   BIGINT,
    fecha_subida TIMESTAMP    NOT NULL DEFAULT NOW()
);

CREATE TABLE materiales (
    id                  BIGSERIAL PRIMARY KEY,
    seccion_curso_id    BIGINT       NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    titulo              VARCHAR(200) NOT NULL,
    descripcion         TEXT,
    enlace              VARCHAR(500),
    archivo_id          BIGINT,
    archivo_nombre      VARCHAR(255),
    archivo_tipo        VARCHAR(150),
    archivo_tamanio     BIGINT,
    autor_id            BIGINT,
    fecha_publicacion   TIMESTAMP    NOT NULL DEFAULT NOW(),
    fecha_actualizacion TIMESTAMP,
    tipo                VARCHAR(20),                -- TEXTO | ARCHIVO | ENLACE
    visible             BOOLEAN      NOT NULL DEFAULT TRUE,
    carpeta_id          BIGINT                      -- carpetas(id); null = sin carpeta
);

CREATE TABLE actividades (
    id                  BIGSERIAL PRIMARY KEY,
    seccion_curso_id    BIGINT       NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    tipo                VARCHAR(20)  NOT NULL CHECK (tipo IN ('TAREA', 'CUESTIONARIO', 'ACTIVIDAD')),
    titulo              VARCHAR(200) NOT NULL,
    instrucciones       TEXT,
    fecha_limite        TIMESTAMP    NOT NULL,
    puntaje_maximo      FLOAT(53)    NOT NULL DEFAULT 20,
    permite_tardia      BOOLEAN      NOT NULL DEFAULT FALSE,
    archivo_id          BIGINT,
    archivo_nombre      VARCHAR(255),
    archivo_tipo        VARCHAR(150),
    archivo_tamanio     BIGINT,
    enlace              VARCHAR(500),
    evaluacion_id       BIGINT,                     -- columna del registro de notas
    autor_id            BIGINT,
    fecha_publicacion   TIMESTAMP    NOT NULL DEFAULT NOW(),
    fecha_actualizacion TIMESTAMP,
    visible             BOOLEAN      NOT NULL DEFAULT TRUE,
    intentos_permitidos INTEGER      NOT NULL DEFAULT 1,
    carpeta_id          BIGINT,
    formatos_permitidos VARCHAR(100)                -- PDF,WORD,EXCEL,PPT,IMAGEN (vacío = todos)
);

CREATE TABLE preguntas_cuestionario (
    id                 BIGSERIAL PRIMARY KEY,
    actividad_id       BIGINT    NOT NULL REFERENCES actividades(id) ON DELETE CASCADE,
    orden              INTEGER   NOT NULL,
    enunciado          TEXT      NOT NULL,
    respuesta_correcta INTEGER   NOT NULL,          -- UNICA: índice desde 0 | MULTIPLE: máscara de bits
    puntos             FLOAT(53) NOT NULL DEFAULT 1,
    tipo               VARCHAR(10) NOT NULL DEFAULT 'UNICA'
);

CREATE TABLE pregunta_opciones (
    pregunta_id BIGINT       NOT NULL REFERENCES preguntas_cuestionario(id) ON DELETE CASCADE,
    posicion    INTEGER      NOT NULL,
    texto       VARCHAR(500) NOT NULL,
    PRIMARY KEY (pregunta_id, posicion)
);

CREATE TABLE entregas (
    id                 BIGSERIAL PRIMARY KEY,
    actividad_id       BIGINT      NOT NULL REFERENCES actividades(id) ON DELETE CASCADE,
    estudiante_id      BIGINT      NOT NULL REFERENCES estudiantes(id) ON DELETE CASCADE,
    texto              TEXT,
    enlace             VARCHAR(500),
    archivo_id         BIGINT,
    archivo_nombre     VARCHAR(255),
    archivo_tipo       VARCHAR(150),
    archivo_tamanio    BIGINT,
    fecha_entrega      TIMESTAMP   NOT NULL DEFAULT NOW(),
    tardia             BOOLEAN     NOT NULL DEFAULT FALSE,
    estado             VARCHAR(20) NOT NULL DEFAULT 'ENTREGADA' CHECK (estado IN ('ENTREGADA', 'CALIFICADA')),
    puntaje            FLOAT(53),
    comentario_docente TEXT,
    fecha_calificacion TIMESTAMP,
    intentos           INTEGER     NOT NULL DEFAULT 1,
    CONSTRAINT entregas_actividad_estudiante_unique UNIQUE (actividad_id, estudiante_id)
);

-- Historial de envíos de una entrega: "Entrega 1", "Entrega 2"...
CREATE TABLE entrega_envios (
    id              BIGSERIAL PRIMARY KEY,
    entrega_id      BIGINT       NOT NULL REFERENCES entregas(id) ON DELETE CASCADE,
    numero          INTEGER      NOT NULL,
    texto           TEXT,
    enlace          VARCHAR(500),
    archivo_id      BIGINT,
    archivo_nombre  VARCHAR(255),
    archivo_tipo    VARCHAR(150),
    archivo_tamanio BIGINT,
    puntaje         FLOAT(53),                      -- cuestionarios: puntaje de ese intento
    respuestas      TEXT,                           -- cuestionarios: respuestas de ese intento (separadas por coma)
    fecha           TIMESTAMP    NOT NULL DEFAULT NOW(),
    tardia          BOOLEAN      NOT NULL DEFAULT FALSE
);

CREATE TABLE entrega_respuestas (
    entrega_id BIGINT  NOT NULL REFERENCES entregas(id) ON DELETE CASCADE,
    posicion   INTEGER NOT NULL,
    opcion     INTEGER NOT NULL,
    PRIMARY KEY (entrega_id, posicion)
);

CREATE TABLE asistencias (
    id               BIGSERIAL PRIMARY KEY,
    seccion_curso_id BIGINT      NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    estudiante_id    BIGINT      NOT NULL REFERENCES estudiantes(id) ON DELETE CASCADE,
    fecha            DATE        NOT NULL,
    estado           VARCHAR(15) NOT NULL CHECK (estado IN ('PRESENTE', 'TARDANZA', 'FALTA', 'JUSTIFICADA')),
    observacion      VARCHAR(300),
    registrado_por   BIGINT,
    fecha_registro   TIMESTAMP   NOT NULL DEFAULT NOW(),
    CONSTRAINT asistencias_unique UNIQUE (seccion_curso_id, estudiante_id, fecha)
);

-- Carpetas del contenido de un curso (cada una pertenece a un bimestre)
CREATE TABLE carpetas (
    id               BIGSERIAL PRIMARY KEY,
    seccion_curso_id BIGINT       NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    periodo_id       BIGINT       NOT NULL REFERENCES periodos(id),
    nombre           VARCHAR(120) NOT NULL,
    visible          BOOLEAN      NOT NULL DEFAULT TRUE,
    fecha_creacion   TIMESTAMP    NOT NULL DEFAULT NOW()
);

-- Asistencia generada por el docente durante la hora de clase
CREATE TABLE sesiones_asistencia (
    id               BIGSERIAL PRIMARY KEY,
    seccion_curso_id BIGINT    NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    fecha            DATE      NOT NULL,
    hora_inicio      TIME      NOT NULL,
    generada_por     BIGINT,
    fecha_generacion TIMESTAMP NOT NULL DEFAULT NOW(),
    CONSTRAINT sesiones_asistencia_unique UNIQUE (seccion_curso_id, fecha)
);


-- ============================================================
-- 7. CALIFICACIONES (Sprint 5) — escala 0 a 20
-- ============================================================

CREATE TABLE evaluaciones (
    id               BIGSERIAL PRIMARY KEY,
    seccion_curso_id BIGINT       NOT NULL REFERENCES seccion_cursos(id) ON DELETE CASCADE,
    periodo_id       BIGINT       NOT NULL REFERENCES periodos(id),
    nombre           VARCHAR(120) NOT NULL,
    tipo             VARCHAR(20)  NOT NULL DEFAULT 'OTRO',
    peso             INTEGER      NOT NULL DEFAULT 1 CHECK (peso BETWEEN 1 AND 10),
    fecha            DATE,
    actividad_id     BIGINT,
    fecha_registro   TIMESTAMP    NOT NULL DEFAULT NOW()
);

CREATE TABLE notas (
    id                  BIGSERIAL PRIMARY KEY,
    evaluacion_id       BIGINT    NOT NULL REFERENCES evaluaciones(id) ON DELETE CASCADE,
    estudiante_id       BIGINT    NOT NULL REFERENCES estudiantes(id) ON DELETE CASCADE,
    valor               FLOAT(53) NOT NULL CHECK (valor >= 0 AND valor <= 20),
    comentario          VARCHAR(300),
    registrado_por      BIGINT,
    fecha_registro      TIMESTAMP NOT NULL DEFAULT NOW(),
    fecha_actualizacion TIMESTAMP,
    CONSTRAINT notas_evaluacion_estudiante_unique UNIQUE (evaluacion_id, estudiante_id)
);

-- Correcciones de notas (quién, cuándo, valor anterior y nuevo, motivo)
CREATE TABLE notas_historial (
    id             BIGSERIAL PRIMARY KEY,
    evaluacion_id  BIGINT    NOT NULL,
    estudiante_id  BIGINT    NOT NULL,
    valor_anterior FLOAT(53),
    valor_nuevo    FLOAT(53),
    motivo         VARCHAR(300),
    usuario_id     BIGINT,
    usuario_nombre VARCHAR(100),
    fecha          TIMESTAMP NOT NULL DEFAULT NOW()
);


-- ============================================================
-- 8. REUNIONES (Sprint 6)
-- ============================================================

-- Horarios de atención semanales (1 = lunes ... 6 = sábado)
CREATE TABLE disponibilidades (
    id               BIGSERIAL PRIMARY KEY,
    usuario_id       BIGINT      NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    dia              INTEGER     NOT NULL CHECK (dia BETWEEN 1 AND 6),
    hora_inicio      TIME        NOT NULL,
    hora_fin         TIME        NOT NULL,
    duracion_minutos INTEGER     NOT NULL DEFAULT 30,
    modalidad        VARCHAR(15) NOT NULL DEFAULT 'PRESENCIAL' CHECK (modalidad IN ('PRESENCIAL', 'VIRTUAL')),
    lugar            VARCHAR(300),
    activo           BOOLEAN     NOT NULL DEFAULT TRUE,
    fecha_registro   TIMESTAMP   NOT NULL DEFAULT NOW()
);

CREATE TABLE citas (
    id                  BIGSERIAL PRIMARY KEY,
    responsable_id      BIGINT       NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    padre_id            BIGINT       NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
    estudiante_id       BIGINT REFERENCES estudiantes(id) ON DELETE SET NULL,
    fecha               DATE         NOT NULL,
    hora_inicio         TIME         NOT NULL,
    hora_fin            TIME         NOT NULL,
    modalidad           VARCHAR(15)  NOT NULL DEFAULT 'PRESENCIAL',
    lugar               VARCHAR(300),
    motivo              VARCHAR(500) NOT NULL,
    origen              VARCHAR(20)  NOT NULL CHECK (origen IN ('SOLICITUD_PADRE', 'PROGRAMADA')),
    estado              VARCHAR(15)  NOT NULL
                        CHECK (estado IN ('PENDIENTE', 'CONFIRMADA', 'RECHAZADA', 'CANCELADA', 'REALIZADA')),
    observacion         VARCHAR(500),
    actualizado_por     BIGINT,
    reprogramaciones    INTEGER      NOT NULL DEFAULT 0,
    fecha_creacion      TIMESTAMP    NOT NULL DEFAULT NOW(),
    fecha_actualizacion TIMESTAMP,
    detalle             TEXT
);


