-- ============================================================
-- 11. DATOS CALCULADOS (entregas, notas y asistencia)
-- Se generan con SQL para no escribir miles de filas a mano.
-- Los "azares" son fijos (hashtext): cada vez que corras el script sale lo mismo.
-- Fecha de referencia del sistema: miércoles 14/10/2026.
-- ============================================================

-- Las secuencias siguen después de los id escritos arriba
DO $$
DECLARE t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['usuarios', 'personal', 'docentes', 'padres_familia', 'estudiantes', 'estudiante_familiar',
        'periodos', 'cursos', 'secciones', 'seccion_cursos', 'horario_bloques', 'archivos', 'carpetas', 'materiales',
        'actividades', 'preguntas_cuestionario', 'evaluaciones', 'entregas', 'entrega_envios', 'comunicados',
        'comunicado_lecturas', 'mensajes', 'mensaje_destinatarios', 'disponibilidades', 'citas']
    LOOP
        EXECUTE format('SELECT setval(pg_get_serial_sequence(%L, ''id''), GREATEST(1, (SELECT COALESCE(MAX(id), 0) FROM %I)), (SELECT COUNT(*) > 0 FROM %I))', t, t, t);
    END LOOP;
END $$;

-- "Nivel" de cada alumno (8 a 18) para que sus notas sean coherentes entre cursos
CREATE TEMP TABLE nivel_alumno AS
SELECT id, CASE WHEN abs(hashtext('w' || id)) % 10 = 0 THEN 8 ELSE 11 + abs(hashtext('n' || id)) % 8 END AS base
FROM estudiantes;

-- Alumnos de cada curso (sección del alumno = sección del curso)
CREATE TEMP TABLE alumno_curso AS
SELECT sc.id AS seccion_curso_id, e.id AS estudiante_id, d.usuario_id AS docente_usuario
FROM seccion_cursos sc
JOIN secciones s ON s.id = sc.seccion_id
JOIN estudiantes e ON e.grado = s.grado AND e.seccion = s.letra AND e.estado = 'Activo'
LEFT JOIN docentes d ON d.id = sc.docente_id;

-- ---------- Entregas de TAREAS ----------
WITH base AS (
    SELECT a.id AS actividad_id, ac.estudiante_id, a.fecha_limite, a.permite_tardia, n.base,
           abs(hashtext('e' || a.id || '-' || ac.estudiante_id)) % 100 AS r,
           abs(hashtext('b' || a.id || '-' || ac.estudiante_id)) AS r2
    FROM actividades a
    JOIN alumno_curso ac ON ac.seccion_curso_id = a.seccion_curso_id
    JOIN nivel_alumno n ON n.id = ac.estudiante_id
    WHERE a.tipo = 'TAREA'
      AND NOT EXISTS (SELECT 1 FROM entregas x WHERE x.actividad_id = a.id AND x.estudiante_id = ac.estudiante_id)
), decision AS (
    SELECT *,
           CASE
               WHEN fecha_limite >= TIMESTAMP '2026-10-14 10:00' THEN (CASE WHEN r < 45 THEN 'A_TIEMPO' END)
               WHEN r < 85 THEN 'A_TIEMPO'
               WHEN permite_tardia AND r < 93 THEN 'TARDE'
           END AS envio
    FROM base
), filas AS (
    SELECT *,
           CASE WHEN envio = 'TARDE' THEN fecha_limite + make_interval(hours => 1 + r2 % 40)
                WHEN fecha_limite >= TIMESTAMP '2026-10-14 10:00' THEN TIMESTAMP '2026-10-14 08:00' - make_interval(hours => r2 % 96)
                ELSE fecha_limite - make_interval(hours => 2 + r2 % 70) END AS fecha,
           (fecha_limite < TIMESTAMP '2026-10-05' OR (fecha_limite < TIMESTAMP '2026-10-14' AND envio = 'A_TIEMPO' AND r2 % 3 = 0)) AS calificada
    FROM decision WHERE envio IS NOT NULL
)
                      fecha_calificacion, intentos)
SELECT actividad_id, estudiante_id,
       (ARRAY['Adjunto el desarrollo de mi tarea.', 'Profesor(a), aquí está mi trabajo resuelto.',
              'Envío mi tarea. Hice los ejercicios en mi cuaderno y los pasé aquí.', 'Les comparto mi trabajo terminado.',
              'Aquí está mi respuesta, gracias.'])[1 + r2 % 5],
       fecha, envio = 'TARDE',
       CASE WHEN calificada THEN 'CALIFICADA' ELSE 'ENTREGADA' END,
       CASE WHEN calificada THEN LEAST(20, GREATEST(5, base + (r2 % 7) - 2 - CASE WHEN envio = 'TARDE' THEN 2 ELSE 0 END)) END,
       CASE WHEN calificada THEN (ARRAY['Buen trabajo, sigue así.', 'Muy bien, ordenado y completo.', 'Revisa los ejercicios 2 y 3.',
              'Excelente presentación.', 'Falta explicar tu procedimiento.', 'Bien, pero cuida la ortografía.', 'Buen esfuerzo.',
              'Debes practicar un poco más.'])[1 + (r2 / 7) % 8] END,
       CASE WHEN calificada THEN LEAST(fecha + INTERVAL '2 days', TIMESTAMP '2026-10-13 20:00') END,
       1
FROM filas;

-- ---------- Entregas de CUESTIONARIOS (se califican solos) ----------
SELECT a.id, ac.estudiante_id,
       a.fecha_limite - make_interval(hours => 2 + abs(hashtext('b' || a.id || '-' || ac.estudiante_id)) % 120),
       FALSE, 'CALIFICADA', 'Calificado automáticamente.', 1
FROM actividades a
JOIN alumno_curso ac ON ac.seccion_curso_id = a.seccion_curso_id
WHERE a.tipo = 'CUESTIONARIO' AND a.fecha_limite < TIMESTAMP '2026-10-14'
  AND abs(hashtext('e' || a.id || '-' || ac.estudiante_id)) % 100 < 90;

-- Respuestas: el alumno acierta más o menos según su nivel
SELECT en.id, p.orden,
       CASE WHEN abs(hashtext('q' || en.id || '-' || p.orden)) % 20 < n.base THEN p.respuesta_correcta
            ELSE (p.respuesta_correcta + 1 + abs(hashtext('x' || en.id || '-' || p.orden)) % 3) % 4 END
FROM entregas en
JOIN actividades a ON a.id = en.actividad_id AND a.tipo = 'CUESTIONARIO'
JOIN preguntas_cuestionario p ON p.actividad_id = a.id
JOIN nivel_alumno n ON n.id = en.estudiante_id;

UPDATE entregas en
SET puntaje = x.puntaje, fecha_calificacion = en.fecha_entrega
FROM (SELECT r.entrega_id, SUM(CASE WHEN r.opcion = p.respuesta_correcta THEN p.puntos ELSE 0 END) AS puntaje
      FROM entrega_respuestas r
      JOIN entregas e2 ON e2.id = r.entrega_id
      JOIN preguntas_cuestionario p ON p.actividad_id = e2.actividad_id AND p.orden = r.posicion
      GROUP BY r.entrega_id) x
WHERE x.entrega_id = en.id;

-- ---------- Historial de envíos ("Entrega 1") de las entregas generadas ----------
                            puntaje, respuestas, fecha, tardia)
SELECT en.id, 1, en.texto, en.enlace, en.archivo_id, en.archivo_nombre, en.archivo_tipo, en.archivo_tamanio,
       CASE WHEN a.tipo = 'CUESTIONARIO' THEN en.puntaje END,
       (SELECT string_agg(r.opcion::TEXT, ',' ORDER BY r.posicion) FROM entrega_respuestas r WHERE r.entrega_id = en.id),
       en.fecha_entrega, en.tardia
FROM entregas en
JOIN actividades a ON a.id = en.actividad_id
WHERE NOT EXISTS (SELECT 1 FROM entrega_envios v WHERE v.entrega_id = en.id);

-- ---------- Notas de las actividades calificadas (van a "Participación") ----------
SELECT a.evaluacion_id, en.estudiante_id, ROUND((en.puntaje / a.puntaje_maximo * 20)::NUMERIC, 2),
       CASE WHEN a.tipo = 'TAREA' THEN en.comentario_docente END, d.usuario_id, en.fecha_calificacion
FROM entregas en
JOIN actividades a ON a.id = en.actividad_id
JOIN seccion_cursos sc ON sc.id = a.seccion_curso_id
LEFT JOIN docentes d ON d.id = sc.docente_id
WHERE en.estado = 'CALIFICADA' AND a.evaluacion_id IS NOT NULL;

-- ---------- Notas de exámenes y comportamiento (las que ya se tomaron) ----------
SELECT ev.id, ac.estudiante_id,
       CASE WHEN ev.nombre = 'Comportamiento' THEN 13 + abs(hashtext('c' || ev.id || '-' || ac.estudiante_id)) % 8
            ELSE LEAST(20, GREATEST(5, n.base + abs(hashtext('x' || ev.id || '-' || ac.estudiante_id)) % 7 - 3)) END,
       ac.docente_usuario, ev.fecha + TIME '18:00'
FROM evaluaciones ev
JOIN alumno_curso ac ON ac.seccion_curso_id = ev.seccion_curso_id
JOIN nivel_alumno n ON n.id = ac.estudiante_id
WHERE ev.actividad_id IS NULL AND ev.fecha < DATE '2026-10-14';

-- Registro inicial de cada nota en el historial
SELECT n.evaluacion_id, n.estudiante_id, NULL, n.valor,
       CASE WHEN ev.actividad_id IS NULL THEN 'Registro inicial' ELSE 'Calificación de la actividad "' || ev.nombre || '"' END,
       n.registrado_por, u.nombre, n.fecha_registro
FROM notas n
JOIN evaluaciones ev ON ev.id = n.evaluacion_id
LEFT JOIN usuarios u ON u.id = n.registrado_por;

-- Una corrección de ejemplo: Juan, Examen Mensual de Matemática del III Bimestre
WITH ev AS (
    SELECT ev.id FROM evaluaciones ev
    JOIN seccion_cursos sc ON sc.id = ev.seccion_curso_id
    JOIN secciones s ON s.id = sc.seccion_id AND s.grado = '5° Primaria' AND s.letra = 'A'
    JOIN cursos c ON c.id = sc.curso_id AND c.nombre = 'Matemática'
    JOIN periodos p ON p.id = ev.periodo_id AND p.bimestre = 3
    WHERE ev.nombre = 'Examen Mensual'
), juan AS (SELECT id FROM estudiantes WHERE dni = '87654321'),
anterior AS (SELECT n.valor FROM notas n, ev, juan WHERE n.evaluacion_id = ev.id AND n.estudiante_id = juan.id)
SELECT ev.id, juan.id, anterior.valor, LEAST(20, anterior.valor + 2), 'Revisión del examen: se sumó la pregunta 5',
       (SELECT id FROM usuarios WHERE usuario = 'DOC45678912'), 'Carlos Mendoza Ruiz', TIMESTAMP '2026-09-22 13:10'
FROM ev, juan, anterior;

UPDATE notas n SET valor = LEAST(20, n.valor + 2), fecha_actualizacion = TIMESTAMP '2026-09-22 13:10'
FROM evaluaciones ev
JOIN seccion_cursos sc ON sc.id = ev.seccion_curso_id
JOIN secciones s ON s.id = sc.seccion_id AND s.grado = '5° Primaria' AND s.letra = 'A'
JOIN cursos c ON c.id = sc.curso_id AND c.nombre = 'Matemática'
JOIN periodos p ON p.id = ev.periodo_id AND p.bimestre = 3
WHERE n.evaluacion_id = ev.id AND ev.nombre = 'Examen Mensual'
  AND n.estudiante_id = (SELECT id FROM estudiantes WHERE dni = '87654321');

-- ---------- Asistencia: una sesión por día de clase (hasta el 13/10) y el registro de cada alumno ----------
-- Algunas fechas quedan sin generar (rojo) y otras generadas sin marcar, como pasa en la realidad.
CREATE TEMP TABLE dias_clase AS
SELECT sc.id AS seccion_curso_id, d::DATE AS fecha, MIN(b.hora_inicio) AS hora_inicio, doc.usuario_id AS docente_usuario
FROM seccion_cursos sc
JOIN horario_bloques b ON b.seccion_curso_id = sc.id
JOIN periodos p ON p.anio = 2026
JOIN LATERAL generate_series(p.fecha_inicio, LEAST(p.fecha_fin, DATE '2026-10-13'), INTERVAL '1 day') d ON TRUE
LEFT JOIN docentes doc ON doc.id = sc.docente_id
WHERE EXTRACT(ISODOW FROM d) = b.dia
GROUP BY sc.id, d::DATE, doc.usuario_id;

SELECT seccion_curso_id, fecha, hora_inicio, docente_usuario, fecha + hora_inicio + INTERVAL '5 minutes'
FROM dias_clase
WHERE abs(hashtext('s' || seccion_curso_id || fecha)) % 40 <> 0;

SELECT ses.seccion_curso_id, ac.estudiante_id, ses.fecha,
       CASE WHEN r < 88 THEN 'PRESENTE' WHEN r < 94 THEN 'TARDANZA' WHEN r < 98 THEN 'FALTA' ELSE 'JUSTIFICADA' END,
       CASE WHEN r >= 88 AND r < 94 THEN 'Llegó ' || (5 + r % 3 * 5) || ' minutos tarde'
            WHEN r >= 98 THEN 'Presentó certificado médico' END,
       ses.generada_por, ses.fecha_generacion + INTERVAL '10 minutes'
FROM sesiones_asistencia ses
JOIN alumno_curso ac ON ac.seccion_curso_id = ses.seccion_curso_id
CROSS JOIN LATERAL (SELECT abs(hashtext('a' || ses.id || '-' || ac.estudiante_id)) % 100 AS r) x
WHERE abs(hashtext('m' || ses.seccion_curso_id || ses.fecha)) % 60 <> 0;

-- Secuencias al día (para que la aplicación siga creando registros sin choques)
DO $$
DECLARE t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['entregas', 'entrega_envios', 'notas', 'notas_historial', 'sesiones_asistencia', 'asistencias']
    LOOP
        EXECUTE format('SELECT setval(pg_get_serial_sequence(%L, ''id''), GREATEST(1, (SELECT COALESCE(MAX(id), 0) FROM %I)), (SELECT COUNT(*) > 0 FROM %I))', t, t, t);
    END LOOP;
END $$;

DROP TABLE nivel_alumno, alumno_curso, dias_clase;


