SELECT rol, COUNT(*) AS cuentas FROM usuarios GROUP BY rol ORDER BY rol;

SELECT s.grado, s.letra, s.turno, d.nombre_completo AS tutor, COUNT(e.id) AS alumnos
FROM secciones s
LEFT JOIN docentes d ON d.id = s.tutor_id
LEFT JOIN estudiantes e ON e.grado = s.grado AND e.seccion = s.letra
GROUP BY s.id, s.grado, s.letra, s.turno, d.nombre_completo
ORDER BY s.id;

SELECT 'actividades' AS tabla, COUNT(*) AS filas FROM actividades UNION ALL
