INSERT INTO entrega_envios (entrega_id, numero, texto, fecha, tardia) VALUES
    (2, 1, 'Mi informe sobre El principito: el libro enseña que lo esencial es invisible a los ojos y que la amistad se cultiva con tiempo.', '2026-10-11 16:40', TRUE);
INSERT INTO comunicados (id, titulo, contenido, anuncio, autor_id, fecha_creacion) VALUES
    (1, 'Reunión de Padres de Familia - III Bimestre', '<p>Estimados padres, les invitamos a la reunión para revisar el progreso académico del <b>III Bimestre</b>.</p><p><b>Fecha:</b> viernes 16 de octubre, 6:00 p. m. — Auditorio principal.</p><ul><li>Presentación de calificaciones.</li><li>Estrategias de apoyo en casa.</li><li>Preguntas y respuestas.</li></ul>', TRUE, 1, '2026-10-12 09:00'),
    (2, 'Fin del III Bimestre y vacaciones de medio año escolar', '<p>El III Bimestre termina el <b>viernes 16 de octubre</b>. Del 19 al 23 de octubre los alumnos tendrán una semana de descanso.</p><p>El IV Bimestre inicia el <b>lunes 26 de octubre</b>.</p>', TRUE, 2, '2026-10-08 10:30'),
    (3, 'Procesión del Señor de los Milagros', '<p>El viernes 23 de octubre acompañaremos la procesión del Señor de los Milagros en el distrito. Los alumnos que participen deben venir con su polo morado.</p>', FALSE, 3, '2026-10-06 11:00'),
    (4, 'Semana de exámenes bimestrales', '<p>Del 13 al 16 de octubre se rendirán los exámenes bimestrales. Revisen en <em>Mis Cursos</em> las fechas de cada curso.</p>', FALSE, 1, '2026-10-05 08:15'),
    (5, 'Capacitación docente: evaluación formativa', '<p>Estimados docentes, el sábado 17 de octubre de 9:00 a 12:00 tendremos la capacitación sobre evaluación formativa en la sala de cómputo.</p>', FALSE, 6, '2026-10-09 15:00'),
    (6, 'Materiales para geometría', '<p>Para la clase del miércoles traer regla, transportador y compás.</p>', FALSE, 7, '2026-10-12 13:10'),
    (7, 'Plan lector: lectura de "El principito"', '<p>Queridos alumnos, esta semana terminamos la lectura de "El principito". Traigan su ficha de lectura completa.</p>', FALSE, 8, '2026-10-07 07:50'),
    (8, 'Campaña de vacunación escolar', '<p>El Centro de Salud de Comas realizará la campaña de vacunación el martes 20 de octubre. Los padres deben firmar la autorización que se envía en la agenda.</p>', FALSE, 5, '2026-09-30 09:40'),
    (9, 'Día de la Educación Inicial y Primaria: actuación', '<p>Agradecemos a todas las familias por su participación en la actuación por el aniversario del colegio. ¡Fue un éxito!</p>', FALSE, 2, '2026-09-21 12:00');
