INSERT INTO mensajes (id, remitente_id, asunto, contenido, fecha_envio, aviso_sistema) VALUES
    (1, 7, 'Chat', 'Juan, recuerda traer regla y compás para la clase de geometría.', '2026-10-12 13:20', FALSE),
    (2, 32, 'Chat', 'Gracias profesor, los llevaré.', '2026-10-12 18:02', FALSE),
    (3, 32, 'Chat', 'Profesor, ya subí la segunda entrega de la tarea de perímetro y área.', '2026-10-13 18:07', FALSE),
    (4, 30, 'Chat', 'Buenas tardes, profesor. Quería consultarle cómo va Juan en Matemática este bimestre.', '2026-10-09 19:30', FALSE),
    (5, 7, 'Chat', 'Buenas tardes, señor Pérez. Juan va bien; solo debe practicar más los problemas con decimales. Si desea, podemos tener una cita.', '2026-10-10 13:05', FALSE),
    (6, 30, 'Chat', 'Perfecto, le solicitaré una cita por Mi Agenda. Muchas gracias.', '2026-10-10 20:15', FALSE),
    (7, 31, 'Chat', 'Miss Rosa, ¿Lucía puede entregar su trabajo de investigación hasta el domingo? Estuvo enferma.', '2026-10-10 08:12', FALSE),
    (8, 8, 'Chat', 'Buenos días, señora Ana. Sí, activé la entrega tardía; quedará marcada como enviada tarde, pero la revisaré.', '2026-10-10 09:40', FALSE),
    (9, 2, 'Chat', 'Profesor Carlos, por favor envíe el consolidado de notas de 5° A antes del 16 de octubre.', '2026-10-08 11:00', FALSE),
    (10, 7, 'Chat', 'Entendido, director. Lo enviaré el jueves.', '2026-10-08 13:00', FALSE),
    (11, 8, 'Chat', 'Carlos, ¿coordinamos la actividad integrada de lectura y matemática para la próxima semana?', '2026-10-13 14:00', FALSE),
    (12, 34, 'Chat', 'Miss, no entendí la pregunta 3 de la ficha de lectura.', '2026-10-13 16:30', FALSE),
    (13, 33, 'Chat', 'Miss, ya envié mi trabajo. Gracias por esperarme.', '2026-10-11 16:45', FALSE),
    (14, 3, 'Chat', 'Profesora Carmen, el aula de 4° A tendrá mantenimiento el viernes; las clases serán en la sala de cómputo.', '2026-10-13 10:20', FALSE),
    (15, NULL, 'Nueva actividad: Tarea: Geometría: perímetro y área', '<p>Tu docente publicó una nueva tarea en <strong>Matemática</strong>: "Tarea: Geometría: perímetro y área". Fecha límite: 16/10/2026 23:59.</p>', '2026-10-05 08:00', TRUE),
    (16, NULL, 'Nueva actividad: Tarea: Geometría: perímetro y área', '<p>Tu docente publicó una nueva tarea en <strong>Matemática</strong>: "Tarea: Geometría: perímetro y área". Fecha límite: 16/10/2026 23:59.</p>', '2026-10-05 08:00', TRUE),
    (17, 9, 'Chat', 'Hola André, no olvides revisar la tarea pendiente del curso.', '2026-10-07 12:40', FALSE),
    (18, 144, 'Chat', 'Sí, profesor(a). Ya la estoy terminando.', '2026-10-07 18:10', FALSE),
